const validJob = (job: SymmyExecutionJob, context: OutboxWorkerHandlerContext) => {
  const planned = job.plan.items.flatMap((item) => item.effects);
  return (
    job.originalPrincipalId === context.actorPrincipalId &&
    planned.length === job.effects.length &&
    new Set(planned.map((effect) => effect.ref.effectId)).size === planned.length &&
    planned.every(
      (effect) =>
        effect.ref.occurrence.record.route.tenantId === context.tenantId &&
        String(effect.ref.occurrence.record.route.integrationRouteId) ===
          String(job.plan.sourceRouteId ?? job.routeId) &&
        effect.ref.routeRevision === (job.plan.sourceRouteRevision ?? job.routeRevision) &&
        effect.ref.mappingVersion === (job.plan.sourceMappingVersion ?? job.mappingVersion) &&
        job.effects.some((saved) => sameEffect(saved.effect, effect)),
    )
  );
};

